class TreeNode {
  int val;
  TreeNode left;
  TreeNode right;

  TreeNode(int x) {
    val = x;
  }
}

class Solution {
  private long dfs(TreeNode node, long current) {
    if (node == null) {
      return 0;
    }
    current = current * 10 + node.val;
    if (node.left == null && node.right == null) {
      return current;
    }
    return dfs(node.left, current) + dfs(node.right, current);
  }

  public int sumNumbers(TreeNode root) {
    return (int) dfs(root, 0);
  }
}

class Solution:
    def sumNumbers(self, root: Optional[TreeNode]) -> int:
        def dfs(node, current):
            if node is None:
                return 0
            current = current * 10 + node.val
            if node.left is None and node.right is None:
                return current
            return dfs(node.left, current) + dfs(node.right, current)

        return dfs(root, 0)

impl Solution {
  pub fn sum_numbers(root: Option<Box<TreeNode>>) -> i32 {
    fn dfs(node: &Option<Box<TreeNode>>, current: i32) -> i32 {
      match node {
        None => 0,
        Some(n) => {
          let value = current * 10 + n.val;
          if n.left.is_none() && n.right.is_none() {
            value
          } else {
            dfs(&n.left, value) + dfs(&n.right, value)
          }
        }
      }
    }
    dfs(&root, 0)
  }
}

const sumNumbers = (root: TreeNode | null): number => {
  const dfs = (node: TreeNode | null, current: number): number => {
    if (node === null) return 0;
    const value = current * 10 + node.val;
    if (node.left === null && node.right === null) return value;
    return dfs(node.left, value) + dfs(node.right, value);
  };
  return dfs(root, 0);
};
